CREATE TABLE IF NOT EXISTS notifications (id INT PRIMARY KEY AUTO_INCREMENT, userId INT NOT NULL, organizationId INT, title VARCHAR(255) NOT NULL, message TEXT, type VARCHAR(100), isRead BOOLEAN DEFAULT false, actionUrl VARCHAR(500), createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, readAt DATETIME, INDEX idx_user_notification (userId), INDEX idx_notification_read (isRead));
CREATE TABLE IF NOT EXISTS tasks (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, assignedTo INT, status ENUM('open', 'inProgress', 'completed', 'cancelled') DEFAULT 'open', priority ENUM('low', 'medium', 'high') DEFAULT 'medium', dueDate DATETIME, createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_org_task (organizationId), INDEX idx_task_status (status));
CREATE TABLE IF NOT EXISTS taskComments (id INT PRIMARY KEY AUTO_INCREMENT, taskId INT NOT NULL, userId INT NOT NULL, comment TEXT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_task_comment (taskId));

